<div class="ai-assistant" id="aiAssistant"><span class="ai-fab-hint" aria-hidden="true"><x-icon name="ai" size="13"/> دستیار هوشمند</span><button class="ai-fab" id="aiFab" type="button" aria-label="دستیار خرید" title="دستیار خرید" aria-expanded="false" aria-controls="aiPanel"><x-icon name="ai" size="28"/></button><section class="ai-panel" id="aiPanel" hidden aria-live="polite"><div class="ai-panel-head"><div class="ai-brand"><span class="ai-brand-icon"><x-icon name="ai" size="17"/></span><div><strong>دستیار خرید</strong><small id="aiStatus">آماده‌ام با شما گفت‌وگو کنم</small></div></div><button class="ai-close" id="aiClose" type="button" aria-label="بستن"><x-icon name="close" size="18"/></button></div><div class="ai-orb" id="aiOrb"><span><x-icon name="ai" size="26"/></span></div><div class="ai-live" id="aiLive">با صدای خودتان بگویید دنبال چه فایلی هستید.</div><div class="ai-transcript" id="aiTranscript"></div><div class="ai-products" id="aiProducts"></div><div class="ai-actions" id="aiActions" hidden></div><button class="ai-mic" id="aiMic" type="button"><x-icon name="mic" size="20"/><span>شروع گفت‌وگوی صوتی</span></button></section></div>
@push('styles')<style>.ai-assistant{position:fixed;left:18px;bottom:calc(env(safe-area-inset-bottom,0px) + 18px);z-index:1200;font-family:inherit}.ai-fab-hint{position:absolute;left:66px;bottom:13px;display:flex;align-items:center;gap:5px;padding:7px 10px;border-radius:10px;background:#111827;color:#fff;font-size:9px;font-weight:900;white-space:nowrap;box-shadow:0 7px 20px rgba(16,24,40,.16);opacity:0;transform:translateX(-8px);pointer-events:none;animation:aiHint 5.5s ease-in-out infinite}.ai-fab-hint:before{content:"";position:absolute;left:-5px;width:10px;height:10px;background:#111827;transform:rotate(45deg)}.ai-fab{position:relative;width:56px;height:56px;padding:0;border:0;border-radius:999px;display:inline-flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#25cff0 0%,#5b7cf6 38%,#a855f7 68%,#ee2fc0 100%);color:#fff;box-shadow:0 4px 14px rgba(168,85,247,.45);cursor:pointer;transition:transform .2s,box-shadow .2s}.ai-fab:after{content:"";position:absolute;inset:-5px;border:1px solid rgba(168,85,247,.3);border-radius:inherit;animation:aiPulse 2.8s infinite}.ai-fab:hover{transform:translateY(-2px) scale(1.04);box-shadow:0 8px 24px rgba(168,85,247,.38)}.ai-panel{position:absolute;left:0;bottom:68px;width:min(390px,calc(100vw - 30px));background:#fff;border:1px solid #e6e8ee;border-radius:24px;overflow:hidden;box-shadow:0 25px 75px rgba(16,24,40,.22);animation:aiIn .22s ease}.ai-panel-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #edf0f4}.ai-brand{display:flex;align-items:center;gap:9px}.ai-brand-icon{width:34px;height:34px;border-radius:11px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#25cff0,#a855f7,#ee2fc0)}.ai-panel-head strong,.ai-panel-head small{display:block}.ai-panel-head strong{font-size:13px}.ai-panel-head small{font-size:9px;color:#667085;margin-top:2px}.ai-close{border:0;width:32px;height:32px;border-radius:10px;background:#f5f6f8;color:#667085;cursor:pointer}.ai-orb{width:92px;height:92px;border-radius:50%;margin:20px auto 10px;display:grid;place-items:center;color:#fff;background:linear-gradient(135deg,#25cff0,#5b7cf6,#a855f7,#ee2fc0);box-shadow:0 10px 35px rgba(168,85,247,.25)}.ai-orb span{width:54px;height:54px;border-radius:50%;display:grid;place-items:center;background:#fff;color:#8b5cf6}.ai-orb.listening{animation:aiListen 1s infinite}.ai-live{text-align:center;min-height:42px;padding:0 18px;font-size:11px;line-height:1.9;color:#344054}.ai-transcript{padding:0 16px;text-align:center;color:#98a2b3;font-size:9px;min-height:18px}.ai-products{display:grid;gap:7px;padding:0 16px}.ai-product{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:10px 11px;border:1px solid #e9eaf0;border-radius:12px;background:#fafbfc}.ai-product b{display:block;font-size:10px;line-height:1.7}.ai-product small{display:block;color:#667085;font-size:9px;margin-top:2px}.ai-product button{border:0;border-radius:9px;background:#eef1ff;color:#4338ca;padding:8px 9px;font:inherit;font-size:9px;font-weight:800;cursor:pointer}.ai-actions{display:flex;gap:7px;padding:10px 16px 0}.ai-actions button{flex:1;border:0;border-radius:10px;padding:10px;font:inherit;font-size:10px;font-weight:800;cursor:pointer}.ai-actions .confirm{background:#111827;color:#fff}.ai-actions .cancel{background:#f2f4f7;color:#475467}.ai-mic{display:flex;align-items:center;justify-content:center;gap:8px;width:calc(100% - 32px);margin:12px 16px 16px;padding:12px;border:0;border-radius:13px;background:#111827;color:#fff;font:inherit;font-size:10px;font-weight:900;cursor:pointer}.ai-mic.listening{background:linear-gradient(135deg,#6541d8,#ee2fc0)}@keyframes aiHint{0%,12%,100%{opacity:0;transform:translateX(-8px)}22%,48%{opacity:1;transform:none}58%{opacity:0;transform:translateX(-8px)}}@keyframes aiPulse{0%,100%{opacity:.2;transform:scale(.98)}50%{opacity:.75;transform:scale(1.08)}}@keyframes aiListen{50%{transform:scale(1.08);box-shadow:0 10px 45px rgba(238,47,192,.38)}}@keyframes aiIn{from{opacity:0;transform:translateY(8px) scale(.98)}to{opacity:1;transform:none}}.ai-guided-highlight{animation:aiHighlight 1.2s ease 2;scroll-margin-top:120px}@keyframes aiHighlight{0%,100%{box-shadow:0 0 0 0 rgba(238,47,192,0)}35%,70%{box-shadow:0 0 0 7px rgba(238,47,192,.16),0 10px 35px rgba(168,85,247,.22);transform:translateY(-2px)}}@media(max-width:600px){.ai-assistant{left:12px;bottom:calc(env(safe-area-inset-bottom,0px) + 12px)}.ai-fab-hint{left:60px}.ai-panel{width:calc(100vw - 24px)}}@media(prefers-reduced-motion:reduce){.ai-fab-hint,.ai-fab:after{animation:none!important}}</style>@endpush
@push('scripts')<script>(function(){const root=document.getElementById('aiAssistant');if(!root)return;const fab=document.getElementById('aiFab'),panel=document.getElementById('aiPanel'),close=document.getElementById('aiClose'),mic=document.getElementById('aiMic'),status=document.getElementById('aiStatus'),live=document.getElementById('aiLive'),orb=document.getElementById('aiOrb'),transcript=document.getElementById('aiTranscript'),products=document.getElementById('aiProducts'),actions=document.getElementById('aiActions');let rec=null,listening=false,busy=false,pending=null;const toggle=open=>{panel.hidden=!open;fab.setAttribute('aria-expanded',open?'true':'false');if(open)window.dispatchEvent(new CustomEvent('ai:opened'))};fab.onclick=()=>toggle(true);document.querySelectorAll('[data-ai-open]').forEach(b=>b.addEventListener('click',()=>toggle(true)));close.onclick=()=>toggle(false);function speak(text){if(!('speechSynthesis'in window))return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fa-IR';u.rate=.96;window.speechSynthesis.speak(u)}function resetActions(){actions.hidden=true;actions.innerHTML='';pending=null}function guide(product){pending=product;actions.hidden=false;actions.innerHTML='<button class="confirm" type="button">بله، برو به صفحه محصول</button><button class="cancel" type="button">فعلاً نه</button>';actions.querySelector('.confirm').onclick=()=>{localStorage.setItem('ds_ai_focus',JSON.stringify({id:product.id,title:product.title,price:product.price}));window.location.href=product.url};actions.querySelector('.cancel').onclick=()=>{resetActions();live.textContent='حتماً. اگر خواستید گزینه دیگری را بررسی می‌کنیم.';speak(live.textContent)}}function renderProducts(items){products.innerHTML='';if(!items?.length)return;items.slice(0,3).forEach((p,i)=>{const el=document.createElement('div');el.className='ai-product';el.innerHTML='<div><b></b><small></small></div><button type="button">معرفی</button>';el.querySelector('b').textContent=p.title;el.querySelector('small').textContent=new Intl.NumberFormat('fa-IR').format(Number(p.price||0))+' تومان';el.querySelector('button').onclick=()=>{const text='این فایل با عنوان '+p.title+' یکی از گزینه‌های مناسب برای درخواست شماست. آیا مایلید صفحه محصول را باز کنم و جزئیات و قیمت را نشان بدهم؟';live.textContent=text;speak(text);guide(p)};products.appendChild(el);if(i===0){const text='گزینه پیشنهادی من «'+p.title+'» است. آیا مایلید صفحه محصول را باز کنم و جزئیات و قیمت را نشان بدهم؟';live.textContent=text;speak(text);guide(p)}})}async function ask(text){if(busy)return;busy=true;resetActions();products.innerHTML='';status.textContent='در حال بررسی محصولات واقعی…';live.textContent='در حال جستجو در محتوای فایل‌ها…';try{const r=await fetch('{{ route('ai.chat') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({message:text})});const d=await r.json();transcript.textContent='«'+text+'»';renderProducts(d.products||[]);if(!(d.products||[]).length){live.textContent=d.message||'فعلاً محصول مناسبی پیدا نکردم.';speak(live.textContent)}status.textContent='گفت‌وگو ادامه دارد'}catch(e){live.textContent='ارتباط با دستیار برقرار نشد؛ دوباره تلاش کنید.';speak(live.textContent)}finally{busy=false}}function stop(){if(rec)try{rec.stop()}catch(e){}listening=false;mic.classList.remove('listening');orb.classList.remove('listening');mic.querySelector('span').textContent='شروع گفت‌وگوی صوتی'}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){rec=new SR();rec.lang='fa-IR';rec.interimResults=true;rec.continuous=false;rec.onstart=()=>{listening=true;mic.classList.add('listening');orb.classList.add('listening');status.textContent='دارم گوش می‌دهم…';live.textContent='صحبت کنید'};rec.onresult=e=>{let t='';for(let i=e.resultIndex;i<e.results.length;i++)t+=e.results[i][0].transcript;if(e.results[e.results.length-1].isFinal){stop();ask(t)}};rec.onerror=()=>{stop();live.textContent='صدای شما دریافت نشد؛ دوباره تلاش کنید'};rec.onend=()=>{if(listening)stop()};mic.onclick=()=>{if(listening)stop();else try{rec.start()}catch(e){}}}else{mic.disabled=true;live.textContent='ورودی صوتی در این مرورگر پشتیبانی نمی‌شود.'}const focus=localStorage.getItem('ds_ai_focus');if(focus){try{JSON.parse(focus);localStorage.removeItem('ds_ai_focus');window.setTimeout(()=>{const target=document.querySelector('[data-ai-price]')||document.querySelector('#productPrice');if(target){target.scrollIntoView({behavior:'smooth',block:'center'});target.classList.add('ai-guided-highlight');setTimeout(()=>target.classList.remove('ai-guided-highlight'),2600)}},450)}catch(e){localStorage.removeItem('ds_ai_focus')}}})();</script>@endpush